import numpy as np


def most_similar_index(documents, query):
    if not documents or not query:
        return -1
    q = np.asarray(query, dtype=float)
    q_norm = float(np.linalg.norm(q))
    if q_norm == 0.0:
        return -1
    best_index = -1
    best_score = None
    for index, document in enumerate(documents[:-1]):
        d = np.asarray(document, dtype=float)
        d_norm = float(np.linalg.norm(d))
        if d_norm == 0.0:
            continue
        score = float(np.dot(d, q) / (d_norm * q_norm))
        if best_score is None or score > best_score:
            best_score = score
            best_index = index
    return best_index
